    21	// (game art, screenshots, the Nxeon logo) rendered as broken images in the
    22	// admin panel while the identical page worked fine for customers.
    23	const STATIC_ASSET_RE =
    24	  /\.(?:png|jpe?g|gif|webp|avif|svg|ico|mp4|webm|woff2?|css|json|txt|md|html)$/i;
    25	
    26	/**
    27	 * Reachable on every host regardless of portal mode: Next internals, the API
    28	 * surface every portal's own client code calls (chat SSE, uploads, etc.),
    29	 * the auth utility pages every login form links to, and static files under
    30	 * public/. Everything else is scoped to exactly one portal below.
    31	 */
    32	function isUniversallyAllowed(pathname: string): boolean {
    33	  return (
    34	    pathname.startsWith("/_next") ||
    35	    pathname.startsWith("/api/") ||
    36	    pathname === "/favicon.ico" ||
    37	    pathname.startsWith("/.well-known/") ||
    38	    pathname === "/forgot-password" ||
    39	    pathname === "/reset-password" ||
    40	    // Both portal layouts redirect a staff/admin account without 2FA here to
    41	    // enroll (enforce_staff_2fa) -- account security settings aren't
    42	    // customer-specific, and blocking this would stand between a legitimate
    43	    // staff member and the one page that lets them satisfy the requirement.
    44	    pathname === "/dashboard/settings" ||
    45	    STATIC_ASSET_RE.test(pathname) ||
    46	    // public/ also ships two vendored JS trees the portals load at runtime: the
    47	    // noVNC console client (admin impersonation / VNC console) and skinview3d.
    48	    // `.js` is deliberately NOT in the extension list above (a bare .js path
    49	    // elsewhere is not a public asset), so they are allowed by directory.
    50	    pathname.startsWith("/novnc/") ||
    51	    pathname.startsWith("/vendor/")
    52	  );
    53	}
    54	
    55	/**
    56	 * Confines the admin/staff hostnames to exactly their own portal.
    57	 *
    58	 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
    59	 * direction -- /admin and /staff 404 on any host that isn't their own
    60	 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
    61	 * admin/staff hostnames proxy to the exact same Next.js backend as the main
    62	 * site, so /dashboard, /login, /register, and every marketing page were
    63	 * equally reachable there too -- confirmed live 2026-09-02, a customer's full
    64	 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
    65	 * Not a data leak (they only ever saw their own account), but it defeats the
    66	 * point of a separate, minimal, operations-only surface, and reduces
    67	 * whatever "hard to guess" value the admin subdomain has by leaving it fully
    68	 * browsable/indexable as a second copy of the public site.
    69	 *
    70	 * Together with the two layouts' existing checks this makes the mapping
    71	 * exact: admin host <-> /admin only, staff host <-> /staff only, every other
    72	 * host <-> everything except /admin and /staff.
    73	 */
    74	const NXM_EXACT = new Set<string>(NXM_LIVE_ROUTES.exact);
    75	const NXM_PATTERNS = NXM_LIVE_ROUTES.patterns.map((p) => new RegExp(p));
