    77	export function middleware(req: NextRequest) {
    78	  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
    79	  const { pathname } = req.nextUrl;
    80	
    81	  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
    82	  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
    83	  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
    84	  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);
    85	
    86	  // Cyrus dual-host (CYRUS_DOMAIN_MODE, off by default). The internal Cyrus-host page tree is never reachable by
    87	  // its own URL; on the Cyrus host only the Cyrus surface exists (lib/cyrus/bridge/routing.ts). The marker header
    88	  // is set ONLY here and stripped from every incoming request, so a client can never claim to be on the Cyrus host.
    89	  if (pathname === CYRUS_HOST_TREE || pathname.startsWith(CYRUS_HOST_TREE + "/")) {
    90	    return new NextResponse("Not found.", { status: 404 });
    91	  }
    92	  const bridge = bridgeConfig();
    93	  if (isCyrusHost(host, bridge)) {
    94	    const r = cyrusHostRoute({ pathname, search: req.nextUrl.search, method: req.method, cfg: bridge });
    95	    if (r.kind === "notfound") return new NextResponse("Not found.", { status: 404 });
    96	    if (r.kind === "redirect") return NextResponse.redirect(new URL(r.url, bridge.cyrusOrigin), r.status);
    97	    const h = new Headers(req.headers);
    98	    h.set(CYRUS_HOST_HEADER, "1");
    99	    h.set("x-pathname", r.kind === "rewrite" ? r.pathname : pathname);
   100	    h.set("x-search", req.nextUrl.search);
   101	    if (r.kind === "rewrite") {
   102	      const url = req.nextUrl.clone();
   103	      url.pathname = r.pathname;
   104	      return NextResponse.rewrite(url, { request: { headers: h } });
   105	    }
   106	    return NextResponse.next({ request: { headers: h } });
   107	  }
   108	
   109	  // SEO: www.<apex> served a full 200 duplicate of the site (canonicals pointed at the apex, but
   110	  // two crawlable hosts split link equity and crawl budget). 301 it to the canonical host.
   111	  if (host.startsWith("www.") && !isAdminHost && !isStaffHost && (req.method === "GET" || req.method === "HEAD")) {
   112	    try {
   113	      const canon = new URL(process.env.APP_URL ?? "");
   114	      if (host === `www.${canon.hostname}`) {
   115	        const url = req.nextUrl.clone();
   116	        url.protocol = canon.protocol;
   117	        url.host = canon.host;
   118	        url.port = canon.port;
   119	        return NextResponse.redirect(url, 301);
   120	      }
   121	    } catch {
   122	      /* APP_URL unset/invalid: leave www alone */
   123	    }
   124	  }
   125	
   126	  // Draft site designs (app/newwebsitev1..v8): reachable by URL, linked from no live page, noindex.
   127	  // They have no business on a production host at all, so 404 them unless an operator opts in
   128	  // (NXEON_DRAFT_SITES=1, e.g. on a design sandbox). The files stay in the repo; nothing is deleted.
   129	  if (process.env.NXEON_DRAFT_SITES !== "1" && /^\/newwebsitev[0-9]+(?:\/|$)/.test(pathname)) {
   130	    return new NextResponse("Not found.", { status: 404, headers: { "x-robots-tag": "noindex" } });
   131	  }
   132	
   133	  // An admin impersonating a customer (lib/auth.ts's setImpersonation) needs to
   134	  // browse the FULL customer app -- /dashboard, /checkout, etc. -- from their own
   135	  // admin host, since impersonation swaps identity without changing host. Only
   136	  // ADMIN can ever hold this cookie (EMPLOYEE/staff can never impersonate -- see
   137	  // setImpersonation's own role check), so this only ever loosens the admin
   138	  // host. We only check the cookie's PRESENCE here, not its signature/validity
   139	  // -- that's exactly as strong as this gate needs to be: a forged or expired
   140	  // token still gets fully re-verified by impersonating()/currentUser() at the
   141	  // page/action layer, so a bad cookie here just falls back to "no session",
   142	  // never to unauthorized access.
   143	  const impCookieName = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
   144	  const isImpersonating = isAdminHost && req.cookies.has(impCookieName);
   145	
   146	  if ((isAdminHost || isStaffHost) && !isImpersonating) {
   147	    const ownPrefix = isAdminHost ? "/admin" : "/staff";
   148	    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";
   149	
   150	    // The What's New admin preview renders the real customer dashboard
   151	    // components, so it lives under /dashboard; the page itself is gated by
   152	    // requireArea("platform"). Without this, the admin's own "Preview" link 404s.
   153	    const adminPreview = isAdminHost && pathname.startsWith("/dashboard/whats-new/preview/");
   154	    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix) && !adminPreview) {
   155	      // The shared /login page (and any stray redirect to it -- logout()
   156	      // always sends there, regardless of who's logging out) lands on this
   157	      // host's own dedicated login instead of 404ing a signed-out visitor.
   158	      if (pathname === "/login") {
   159	        const url = req.nextUrl.clone();
   160	        url.pathname = ownLogin;
   161	        return NextResponse.redirect(url);
   162	      }
   163	      // The bare root -- where someone typing/bookmarking just the hostname
   164	      // lands -- goes to the portal itself rather than 404ing. The admin
   165	      // vhost happens to have its own nginx-level `location = / return 302
   166	      // /admin` that already covered this there (confirmed live), but the
   167	      // staff vhost has no equivalent, so its root 404'd under this same
   168	      // isolation logic. Handling it here covers both hosts the same way
   169	      // regardless of nginx config: an authenticated visit shows the portal,
   170	      // an unauthenticated one gets bounced on to ownLogin by the layout's
   171	      // own existing redirect -- no new auth logic needed either way.
   172	      if (pathname === "/") {
   173	        const url = req.nextUrl.clone();
   174	        url.pathname = ownPrefix;
   175	        return NextResponse.redirect(url);
   176	      }
   177	      return new NextResponse("Not found.", { status: 404 });
   178	    }
   179	  }
   180	
   181	  // Server Components have no built-in way to read the current pathname --
   182	  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
   183	  // their own /login sub-route (public, no Shell, no auth redirect) without
   184	  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
   185	  // downstream Server Component actually sees it.
   186	  const requestHeaders = new Headers(req.headers);
   187	  requestHeaders.delete(CYRUS_HOST_HEADER);
   188	  requestHeaders.set("x-pathname", pathname);
   189	  // Same reasoning, for the query string: app/dashboard/layout.tsx's
   190	  // logged-out redirect needs the FULL URL a marketing "Deploy" button sent a
   191	  // visitor to (e.g. `/dashboard/deploy?product=game&family=valheim&tier=...`,
   192	  // see lib/deploy-intent.ts) so it can send them to `/login?next=<that URL>`
   193	  // instead of a bare `/login` that drops the selection the customer already
   194	  // made. Kept separate from `x-pathname` rather than folded into it so every
   195	  // existing exact-pathname comparison (`pathname === "/admin/login"`, etc.)
   196	  // keeps working unchanged.
   197	  requestHeaders.set("x-search", req.nextUrl.search);
   198	
   199	  // The new marketing site (app/nxm) at the real URLs — the launch switch.
   200	  // With NXM_ROOT=1 every URL it owns (app/nxm/_data/live-routes.json, from
   201	  // scripts/nxm-live-routes.ts) is served from app/nxm, and any /nxm/<route>
   202	  // link left over from staging 301s to its real URL. Unset NXM_ROOT and
   203	  // restart to roll back to the old marketing pages instantly — they're
   204	  // untouched. Main host only; admin/staff hosts returned above.
   205	  if (process.env.NXM_ROOT === "1" && !isAdminHost && !isStaffHost) {
   206	    if (pathname === "/nxm" || pathname.startsWith("/nxm/")) {
   207	      if ((req.method === "GET" || req.method === "HEAD") && !/\.[a-z0-9]{2,5}$/i.test(pathname)) {
   208	        const url = req.nextUrl.clone();
   209	        url.pathname = pathname.slice(4) || "/";
   210	        return NextResponse.redirect(url, 301);
   211	      }
   212	    } else if (!isCyrusModsPath(pathname) && (NXM_EXACT.has(pathname) || NXM_PATTERNS.some((re) => re.test(pathname)))) {
   213	      const url = req.nextUrl.clone();
   214	      url.pathname = pathname === "/" ? "/nxm" : "/nxm" + pathname;
   215	      const res = NextResponse.rewrite(url, { request: { headers: requestHeaders } });
   216	      // Anonymous mod pages may be cached by a shared cache / revalidated cheaply (lib/seo-cache.ts); never when a session cookie is present.
   217	      const cc = anonModCacheControl({ method: req.method, pathname, search: req.nextUrl.search, cookie: req.headers.get("cookie"), authorization: req.headers.get("authorization"), sessionCookieName: process.env.NXEON_COOKIE_NAME ?? "nxeon_session" });
   218	      if (cc) { res.headers.set("Cache-Control", cc); res.headers.append("Vary", "Cookie"); }
   219	      return res;
   220	    }
   221	  }
   222	  return NextResponse.next({ request: { headers: requestHeaders } });
   223	}
   224	
   225	/**
   226	 * NxLabs "Cyrus Mods" (/mods/cyrus, /mods/cyrus/<slug>) is served by app/(marketing)/mods/cyrus
   227	 * even with NXM_ROOT on: the nxm pattern ^/mods/[^/]+/[^/]+$ would otherwise send /mods/cyrus/<slug>
   228	 * to the catalogue mod page, and gated per-viewer pages must never get the anonymous cache header.
   229	 */
   230	function isCyrusModsPath(p: string): boolean {
   231	  return p === "/mods/cyrus" || p.startsWith("/mods/cyrus/");
   232	}
