     1	// Dual-host routing decision for the Cyrus host (cyrus.my). PURE + Edge-safe: middleware.ts calls it, tests pin it.
     2	// The same app serves both hosts; on the Cyrus host only the Cyrus surface exists, everything else is either handed
     3	// to Nxeon (portal pages) or 404s. The marketing landing at "/" is nginx's static page; if "/" reaches the app it
     4	// goes to the studio.
     5	import type { BridgeConfig } from "./config";
     6	import { APP_BASE, CYRUS_APP_PATHS } from "../app/flags";
     7	
     8	export type HostRoute =
     9	  | { kind: "pass" }
    10	  | { kind: "rewrite"; pathname: string }
    11	  | { kind: "redirect"; url: string; status: 302 | 307 }
