// On the Cyrus host (cyrus.my, middleware marker + CYRUS_DOMAIN_MODE) the session is a DIFFERENT cookie
// (`__Host-cyrus_session`, host-only) holding a DIFFERENT token type (`typ: "cyrus_session"`, `aud: "cyrus"`), so a
// Cyrus-host token is never accepted on Nxeon and a Nxeon token is never accepted on the Cyrus host. It is minted
// only by the SSO callback (app/cyrus-host/auth/callback) from a verified Nxeon identity assertion, carries the
// account's sessionVersion like any session, and names its parent Nxeon session (`psh`): revoke the parent (Nxeon
// sign-out, "Revoke" in Settings) and the Cyrus session ends with it. Impersonation never applies on the Cyrus host.

/** True when this request came in on the Cyrus host. */
export async function onCyrusHost(): Promise<boolean> {
  if (!bridgeConfig().enabled) return false;
  try {
    return (await headers()).get(CYRUS_HOST_HEADER) === "1";
  } catch {
    return false;
  }
}
async function sessionCookie(): Promise<{ name: string; cyrus: boolean }> {
  const cyrus = await onCyrusHost();
