/** Restart budget defaults (per grant, so per server). A grant may carry lower numbers, never higher. */
export const RESTART_BUDGET = { perHour: 4, perDay: 12 } as const;
/** Request limits (per grant). */
export const LIMITS = {
  callsPerMinute: 600,
  writesPerMinute: 240,
  writeBytesPerHour: 2 * 1024 * 1024 * 1024,
  maxFileBytes: 64 * 1024 * 1024,
  maxReadBytes: 64 * 1024 * 1024,
  maxListEntries: 5000,
  maxLogLines: 2000,
  maxLogBytes: 512 * 1024,
  /** After a revoke, an operation already in flight may only UNDO what it changed, for this long. */
  rollbackGraceMs: 15 * 60_000,
  maxPathLength: 512,
} as const;

/** Games the bridge can act on today (others are listed on the consent screen as not supported yet). */
export const SUPPORTED_FAMILIES = ["minecraft"] as const;

// ------------------------------------------------------------------------------------------------ path policy
export type PathLayout = {
  /** absolute game folder on the guest, e.g. /opt/mc */
  base: string;
  /** the world folder name (server.properties level-name), e.g. "world" */
  levelName: string;
  /** Cyrus' own records/journals folder on the guest (absolute), or null when it may not write any */
  clientStateDir: string | null;
};
export type PathVerdict = { ok: true; path: string; area: PathArea } | { ok: false; reason: string };
export type PathArea = "plugins" | "mods" | "config" | "resourcepacks" | "datapacks" | "client-state" | "read-only";

const SEG_RE = /^[A-Za-z0-9 _.+()\[\]@,'!#&=~-]{1,128}$/;
const DENY_EXT = /\.(sh|bash|zsh|fish|service|timer|socket|so|dll|dylib|exe|bat|cmd|ps1|py|pl|rb|php|cgi)$/i;
const DENY_SEG = /^(\.ssh|\.gnupg|authorized_keys|known_hosts|\.bashrc|\.profile|\.config)$/i;
/** Files outside the write roots that are READ-only (inventory and version detection). */
const READ_ONLY = ["server.properties", "version_history.json", "bukkit.yml", "spigot.yml", "paper.yml", "purpur.yml"];

/** Normalise and classify an absolute guest path. Refuses anything relative, any `.`/`..`/empty segment, odd characters,
 *  executables/scripts, credential folders, and anything outside the allowed roots. `write` = a mutation is wanted;
 *  `mkdir` = a write that may also create (or remove while empty) the root folders themselves;
 *  `stat` = existence only, which also answers for the folders above the game folder and the state folder. */
export function checkPath(raw: unknown, layout: PathLayout, mode: "read" | "write" | "stat" | "mkdir"): PathVerdict {
  if (typeof raw !== "string" || !raw.startsWith("/") || raw.length > LIMITS.maxPathLength || raw.includes("\0") || raw.includes("\\")) return { ok: false, reason: "path must be an absolute guest path" };
  const p = raw.replace(/\/+$/, "") || "/";
  const segs = p.split("/").slice(1);
  if (segs.some((s) => s === "" || s === "." || s === ".." || !SEG_RE.test(s))) return { ok: false, reason: "path has an empty, relative or unusual segment" };
  if (segs.some((s) => DENY_SEG.test(s))) return { ok: false, reason: "credential folders are never reachable" };
  const base = layout.base.replace(/\/+$/, "");
  const state = layout.clientStateDir?.replace(/\/+$/, "") ?? null;
  if (state && (p === state || p.startsWith(state + "/"))) return { ok: true, path: p, area: "client-state" };
  // stat only: the folders ABOVE the game folder / Cyrus' state folder (an installer checks which parents exist)
  if (mode === "stat" && [base, state].some((r) => r && r.startsWith(p + "/"))) return { ok: true, path: p, area: "read-only" };
  if (mode === "stat") mode = "read";
  // the game folder itself: listing its names (which server jar, which folders) for version detection; nothing written
  if (p === base && mode === "read") return { ok: true, path: p, area: "read-only" };
  if (!p.startsWith(base + "/")) return { ok: false, reason: "outside the game folder" };
  const rel = p.slice(base.length + 1);
  const relSegs = rel.split("/");
  const last = relSegs[relSegs.length - 1];
  if (DENY_EXT.test(last)) return { ok: false, reason: "scripts and native binaries are never written or read" };
  const top = relSegs[0];
  const roots: Record<string, PathArea> = { plugins: "plugins", mods: "mods", config: "config", resourcepacks: "resourcepacks" };
  // mkdir only (and removing it again while EMPTY): the root folders themselves, e.g. a first <world>/datapacks
  if (mode === "mkdir") {
    if (relSegs.length === 1 && roots[top]) return { ok: true, path: p, area: roots[top] };
    if (relSegs.length === 2 && relSegs[1] === "datapacks" && (top === layout.levelName || top === "world")) return { ok: true, path: p, area: "datapacks" };
    mode = "write";
  }
  if (roots[top] && relSegs.length >= (mode === "write" ? 2 : 1)) return { ok: true, path: p, area: roots[top] };
  if (relSegs.length >= (mode === "write" ? 3 : 2) && relSegs[1] === "datapacks" && (top === layout.levelName || top === "world")) return { ok: true, path: p, area: "datapacks" };
  if (mode === "read" && relSegs.length === 1 && READ_ONLY.includes(top)) return { ok: true, path: p, area: "read-only" };
  if (mode === "read" && relSegs.length === 1 && (top === layout.levelName || top === "world")) return { ok: true, path: p, area: "read-only" }; // listing the world folder to find datapacks/
  // the world's level.dat, READ only: its enabled/disabled data pack list (the inventory and the delivery check it)
  if (mode === "read" && relSegs.length === 2 && relSegs[1] === "level.dat" && (top === layout.levelName || top === "world")) return { ok: true, path: p, area: "read-only" };
  return { ok: false, reason: mode === "write" ? "only plugins/, mods/, config/, resourcepacks/ and <world>/datapacks/ may be changed" : "this file is not part of the mod inventory" };
}

/** Scopes as the user ticked them, cleaned: unknown dropped, required added, sorted in display order. */
export function normaliseScopes(input: unknown): Scope[] {
  const picked = new Set<Scope>((Array.isArray(input) ? input : []).filter(isScope));
  for (const s of SCOPES) if (SCOPE_INFO[s].required) picked.add(s);
  return SCOPES.filter((s) => picked.has(s));
}

