    62	// ------------------------------------------------------------------------------------------------ memory store
    63	export function createMemoryGrantStore(): GrantStore & { grants: Map<string, Grant>; calls: CallRecord[] } {
    64	  const grants = new Map<string, Grant>();
    65	  const calls: CallRecord[] = [];
    66	  const idem = new Map<string, { at: number; hit: IdemHit }>();
    67	  const clone = (g: Grant): Grant => ({ ...g, scopes: [...g.scopes] });
    68	  const latest = (client: string, userId: string, serverId: string) =>
    69	    [...grants.values()].filter((g) => g.client === client && g.userId === userId && g.serverId === serverId).sort((a, b) => +b.updatedAt - +a.updatedAt)[0] ?? null;
    70	  return {
    71	    grants, calls,
    72	    async upsert(a) {
    73	      const cur = [...grants.values()].find((g) => g.client === a.client && g.userId === a.userId && g.serverId === a.serverId && g.status === "active");
    74	      if (cur) { cur.scopes = normaliseScopes(a.scopes); cur.consentVersion = a.consentVersion; cur.updatedAt = a.now; return clone(cur); }
    75	      const g: Grant = { id: newGrantId(), client: a.client, userId: a.userId, serverId: a.serverId, scopes: normaliseScopes(a.scopes), status: "active", consentVersion: a.consentVersion, restartPerHour: RESTART_BUDGET.perHour, restartPerDay: RESTART_BUDGET.perDay, createdAt: a.now, updatedAt: a.now, revokedAt: null, revokedBy: null, seenVersion: null, seenLoader: null, seenAt: null };
    76	      grants.set(g.id, g);
    77	      return clone(g);
    78	    },
    79	    async revoke(id, by, now) {
    80	      const g = grants.get(id);
    81	      if (!g) return null;
    82	      if (g.status === "active") { g.status = "revoked"; g.revokedAt = now; g.revokedBy = by; g.updatedAt = now; }
    83	      return clone(g);
    84	    },
    85	    async get(id) { const g = grants.get(id); return g ? clone(g) : null; },
    86	    async active(client, userId, serverId) { const g = latest(client, userId, serverId); return g && g.status === "active" ? clone(g) : null; },
    87	    async latest(client, userId, serverId) { const g = latest(client, userId, serverId); return g ? clone(g) : null; },
    88	    async listForUser(client, userId, opts) { return [...grants.values()].filter((g) => g.client === client && g.userId === userId && (opts?.includeRevoked || g.status === "active")).sort((a, b) => +a.createdAt - +b.createdAt).map(clone); },
    89	    async activeForServer(serverId) { return [...grants.values()].filter((g) => g.serverId === serverId && g.status === "active").map(clone); },
    90	    async record(c) { calls.push({ ...c }); if (calls.length > 100_000) calls.splice(0, 10_000); },
    91	    async countCalls(grantId, call, since) { return calls.filter((c) => c.grantId === grantId && c.call === call && c.status < 300 && c.at >= since).length; },
    92	    async bytesWritten(grantId, since) { return calls.filter((c) => c.grantId === grantId && c.mutation && c.at >= since).reduce((n, c) => n + c.bytes, 0); },
    93	    async touched(grantId, opId, path) { return calls.some((c) => c.grantId === grantId && c.opId === opId && c.mutation && c.status < 300 && c.path === path); },
    94	    async opDid(grantId, opId, call) { return calls.some((c) => c.grantId === grantId && c.opId === opId && (call === "*" ? c.mutation : c.call === call) && c.status < 300); },
    95	    async idemGet(scope, key) {
    96	      const k = `${scope}\n${key}`, v = idem.get(k);
    97	      if (v && v.at < Date.now() - 24 * 3600_000) { idem.delete(k); return null; }
    98	      return v?.hit ?? null;
    99	    },
   100	    async idemPut(scope, key, hit, now) { idem.set(`${scope}\n${key}`, { at: +now, hit }); },
   101	    async recentCalls(a) { return calls.filter((c) => c.userId === a.userId && (!a.serverId || c.serverId === a.serverId)).slice(-a.limit).reverse(); },
   102	    async activePage(after, limit) { return [...grants.values()].filter((g) => g.status === "active" && (!after || g.id > after)).sort((a, b) => (a.id < b.id ? -1 : 1)).slice(0, limit).map(clone); },
   103	    async markSeen(id, a) { const g = grants.get(id); if (g) { g.seenVersion = a.version; g.seenLoader = a.loader; g.seenAt = a.at; } },
   104	  };
   105	}
