   166	export const grantsEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_SERVER_GRANTS === "1";
   167	
   168	/** Events a grant change produces (lib/nxeon-platform/events.ts sends them to the client). */
   169	export type GrantEventSink = (e: { type: "grant.created" | "grant.updated" | "grant.revoked"; grant: Grant; at: Date }) => Promise<void>;
   170	
   171	/** What the consent screen submits: the servers ticked and the optional scopes ticked. `eligible` = ids of the user's
   172	 *  own supported servers (the caller computed them from its own records; anything else is refused). */
   173	export async function applyConsent(store: GrantStore, a: {
   174	  client: PlatformClient; userId: string; serverIds: string[]; scopes: unknown; eligible: Set<string>; now?: Date; onEvent?: GrantEventSink;
   175	}): Promise<{ ok: true; grants: Grant[] } | { ok: false; error: string }> {
   176	  const now = a.now ?? new Date();
   177	  const ids = [...new Set(a.serverIds)];
   178	  if (!ids.length) return { ok: false, error: "Pick at least one server." };
   179	  if (ids.length > 100) return { ok: false, error: "Too many servers at once." };
   180	  if (ids.some((id) => !a.eligible.has(id))) return { ok: false, error: "One of those servers is not yours or cannot be connected." };
   181	  const scopes = normaliseScopes(a.scopes);
   182	  const out: Grant[] = [];
   183	  for (const serverId of ids) {
   184	    const before = await store.active(a.client, a.userId, serverId);
   185	    const g = await store.upsert({ client: a.client, userId: a.userId, serverId, scopes, consentVersion: CONSENT_VERSION, now });
   186	    out.push(g);
   187	    await a.onEvent?.({ type: before ? "grant.updated" : "grant.created", grant: g, at: now }).catch(() => undefined);
   188	  }
   189	  return { ok: true, grants: out };
   190	}
