   192	/** Revoke one of the user's grants (the user's own id is checked: nobody revokes someone else's). */
   193	export async function revokeGrant(store: GrantStore, a: { userId: string; grantId: string; by?: string; now?: Date; onEvent?: GrantEventSink }): Promise<Grant | null> {
   194	  const g = await store.get(a.grantId);
   195	  if (!g || g.userId !== a.userId) return null;
   196	  const now = a.now ?? new Date();
   197	  const r = await store.revoke(g.id, a.by ?? "user", now);
   198	  if (r && g.status === "active") await a.onEvent?.({ type: "grant.revoked", grant: r, at: now }).catch(() => undefined);
   199	  return r;
   200	}
   201	
   202	/** A server is going away: every grant on it ends (and the client is told). */
   203	export async function revokeServerGrants(store: GrantStore, serverId: string, reason: "server_deleted" | "server_transferred" | "admin", onEvent?: GrantEventSink, now = new Date()): Promise<number> {
   204	  let n = 0;
   205	  for (const g of await store.activeForServer(serverId)) {
   206	    const r = await store.revoke(g.id, reason, now);
   207	    if (r) { n++; await onEvent?.({ type: "grant.revoked", grant: r, at: now }).catch(() => undefined); }
   208	  }
   209	  return n;
   210	}
