   212	// process-wide store (the routes share it)
   213	let shared: GrantStore | null = null;
   214	export function setGrantStoreForTests(s: GrantStore | null) { shared = s; }
   215	export async function grantStore(env: Record<string, string | undefined> = process.env): Promise<GrantStore> {
   216	  if (shared) return shared;
   217	  if (env.CYRUS_SERVER_GRANTS_STORE === "sql") {
   218	    const { db } = await import("../db");
   219	    shared = createSqlGrantStore({ query: (q, ...a) => db.$queryRawUnsafe(q, ...a), exec: (q, ...a) => db.$executeRawUnsafe(q, ...a) });
   220	  } else shared = createMemoryGrantStore();
   221	  return shared;
   222	}

