    31	// ------------------------------------------------------------------------------------------------ replay cache
    32	/** Remembers ids until they expire. Bounded: when full, the oldest entries go first (they expire first anyway). */
    33	export class ReplayCache {
    34	  private m = new Map<string, number>();
    35	  constructor(private readonly max = 50_000) {}
    36	  /** true when `id` was already seen (a replay); otherwise records it until `expiresAtMs`. */
    37	  seen(id: string, expiresAtMs: number, nowMs: number): boolean {
    38	    const t = this.m.get(id);
    39	    if (t !== undefined && t > nowMs) return true;
    40	    if (this.m.size >= this.max) {
    41	      for (const [k, exp] of this.m) { if (exp <= nowMs || this.m.size >= this.max) this.m.delete(k); else break; }
    42	    }
    43	    this.m.set(id, expiresAtMs);
    44	    return false;
    45	  }
    46	  get size() { return this.m.size; }
    47	}
