    49	// ------------------------------------------------------------------------------------------------ subject assertions
    50	export const SUBJECT_AUD = "cyrus-api-v1";
    51	export const SUBJECT_MAX_LIFETIME_S = 120;
    52	export const SUBJECT_SKEW_S = 30;
    53	/** Opaque, stable account id (today the Nxeon user id; later an SSO sub). "@" is refused so an email can never be one. */
    54	export const SUBJECT_RE = /^[A-Za-z0-9_:.-]{4,128}$/;
    55	export type SubjectClaims = { v: 1; iss: string; sub: string; aud: string; iat: number; exp: number; jti: string; kid?: string };
    56	export type SubjectKey = { client: string; kid: string; publicKey: KeyObject };
    57	
    58	export function mintSubjectAssertion(claims: SubjectClaims, privateKey: KeyObject): string {
    59	  const p = b64u(JSON.stringify(claims));
    60	  return `${p}.${b64u(edSign(null, Buffer.from(p), privateKey))}`;
    61	}
    62	
    63	export type SubjectCheck = { ok: true; claims: SubjectClaims } | { ok: false; code: "bad_subject"; message: string };
    64	export function verifySubjectAssertion(raw: string | null | undefined, o: { client: string; keys: readonly SubjectKey[]; nowMs: number; replay: ReplayCache }): SubjectCheck {
    65	  const bad = (message: string): SubjectCheck => ({ ok: false, code: "bad_subject", message });
    66	  const s = String(raw ?? "").trim();
    67	  if (!s || s.length > 2048) return bad("subject assertion missing or too long");
    68	  const [p, sig, extra] = s.split(".");
    69	  if (!p || !sig || extra !== undefined) return bad("subject assertion is not payload.signature");
    70	  let c: Record<string, unknown>;
    71	  try { c = JSON.parse(Buffer.from(p, "base64url").toString("utf8")); } catch { return bad("subject payload is not JSON"); }
    72	  if (!c || typeof c !== "object" || Array.isArray(c)) return bad("subject payload is not an object");
    73	  if ("email" in c) return bad("subject assertions carry a stable subject id, never an email");
    74	  if (c.iss !== o.client) return bad("subject issuer is not the calling client");
    75	  const keys = o.keys.filter((k) => k.client === o.client && (c.kid === undefined || k.kid === c.kid));
    76	  const sigBuf = Buffer.from(sig, "base64url");
    77	  if (!keys.some((k) => { try { return edVerify(null, Buffer.from(p), k.publicKey, sigBuf); } catch { return false; } })) return bad("subject signature does not verify");
    78	  if (c.v !== 1) return bad("unsupported subject version");
    79	  if (c.aud !== SUBJECT_AUD) return bad("wrong audience");
    80	  if (typeof c.sub !== "string" || !SUBJECT_RE.test(c.sub)) return bad("subject id is not a stable opaque id");
    81	  if (typeof c.jti !== "string" || !/^[A-Za-z0-9_-]{8,64}$/.test(c.jti)) return bad("subject jti missing");
    82	  const iat = Number(c.iat), exp = Number(c.exp), now = Math.floor(o.nowMs / 1000);
    83	  if (!Number.isInteger(iat) || !Number.isInteger(exp) || exp <= iat) return bad("subject times are invalid");
    84	  if (exp - iat > SUBJECT_MAX_LIFETIME_S) return bad(`subject lifetime exceeds ${SUBJECT_MAX_LIFETIME_S} s`);
    85	  if (iat > now + SUBJECT_SKEW_S) return bad("subject issued in the future");
    86	  if (exp + SUBJECT_SKEW_S < now) return bad("subject expired");
    87	  if (o.replay.seen(`sub:${o.client}:${c.jti}`, (exp + SUBJECT_SKEW_S) * 1000, o.nowMs)) return bad("subject assertion already used");
    88	  return { ok: true, claims: c as unknown as SubjectClaims };
    89	}
