    91	// ------------------------------------------------------------------------------------------------ request signing (HMAC)
    92	export const SIG_HEADERS = { keyId: "cyrus-key-id", ts: "cyrus-timestamp", nonce: "cyrus-nonce", sig: "cyrus-signature" } as const;
    93	export const REQUEST_SKEW_S = 300;
    94	export const canonicalRequest = (method: string, pathWithQuery: string, ts: string, nonce: string, body: string | Buffer) =>
    95	  [method.toUpperCase(), pathWithQuery, ts, nonce, sha256Hex(body)].join("\n");
    96	
    97	export function signRequest(a: { keyId: string; secret: string; method: string; pathWithQuery: string; body: string | Buffer; nowMs: number; nonce?: string }): Record<string, string> {
    98	  const ts = String(Math.floor(a.nowMs / 1000));
    99	  const nonce = a.nonce ?? randomBytes(12).toString("base64url");
   100	  const sig = createHmac("sha256", a.secret).update(canonicalRequest(a.method, a.pathWithQuery, ts, nonce, a.body)).digest("hex");
   101	  return { [SIG_HEADERS.keyId]: a.keyId, [SIG_HEADERS.ts]: ts, [SIG_HEADERS.nonce]: nonce, [SIG_HEADERS.sig]: `v1=${sig}` };
   102	}
   103	
   104	export type RequestCheck = { ok: true; keyId: string } | { ok: false; code: "unsigned" | "unknown_key" | "stale" | "replay" | "bad_signature" };
   105	export function verifyRequest(a: { header: (name: string) => string | null; method: string; pathWithQuery: string; body: string | Buffer; secretFor: (keyId: string) => string | null; nowMs: number; replay: ReplayCache }): RequestCheck {
   106	  const keyId = a.header(SIG_HEADERS.keyId), ts = a.header(SIG_HEADERS.ts), nonce = a.header(SIG_HEADERS.nonce), sig = a.header(SIG_HEADERS.sig);
   107	  if (!keyId || !ts || !nonce || !sig || !/^\d{9,11}$/.test(ts) || !/^[A-Za-z0-9_-]{8,64}$/.test(nonce)) return { ok: false, code: "unsigned" };
   108	  const secret = a.secretFor(keyId);
   109	  if (!secret) return { ok: false, code: "unknown_key" };
   110	  if (Math.abs(Math.floor(a.nowMs / 1000) - Number(ts)) > REQUEST_SKEW_S) return { ok: false, code: "stale" };
   111	  const want = `v1=${createHmac("sha256", secret).update(canonicalRequest(a.method, a.pathWithQuery, ts, nonce, a.body)).digest("hex")}`;
   112	  if (!safeEqual(sig, want)) return { ok: false, code: "bad_signature" };
   113	  if (a.replay.seen(`req:${keyId}:${nonce}`, (Number(ts) + REQUEST_SKEW_S) * 1000, a.nowMs)) return { ok: false, code: "replay" };
   114	  return { ok: true, keyId };
   115	}
