   117	// ------------------------------------------------------------------------------------------------ webhooks
   118	export const WEBHOOK_TOLERANCE_S = 300;
   119	export const signWebhook = (secret: string, id: string, timestamp: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${timestamp}.${body}`).digest("hex")}`;
   120	
   121	/** Receiver side (what Nxeon runs): signature, freshness, then exactly-once by id. */
   122	export function verifyWebhook(a: { secret: string; id: string | null; timestamp: string | null; body: string; signature: string | null; nowMs: number; replay: ReplayCache }): { ok: true } | { ok: false; code: "unsigned" | "stale" | "bad_signature" | "duplicate" } {
   123	  if (!a.id || !a.timestamp || !a.signature || !/^\d{9,11}$/.test(a.timestamp)) return { ok: false, code: "unsigned" };
   124	  if (Math.abs(Math.floor(a.nowMs / 1000) - Number(a.timestamp)) > WEBHOOK_TOLERANCE_S) return { ok: false, code: "stale" };
   125	  // several "v1=" values may be sent during a secret rotation
   126	  const want = signWebhook(a.secret, a.id, a.timestamp, a.body);
   127	  if (!a.signature.split(/[ ,]+/).some((s) => safeEqual(s, want))) return { ok: false, code: "bad_signature" };
   128	  if (a.replay.seen(`wh:${a.id}`, a.nowMs + 24 * 3600_000, a.nowMs)) return { ok: false, code: "duplicate" };
   129	  return { ok: true };
   130	}

