193	export type PreinstallFinding = { id: string; class: string; severity: "blocking" | "warning" | "info"; message: string };
194	export type PreinstallReport = {
195	  ok: boolean;
196	  blocking: PreinstallFinding[];
197	  warnings: PreinstallFinding[];
198	  /** Mods-tab installs that collide with this mod (the user resolves these in the Mods tab) */
199	  modsTab: { name: string; version: string | null; fileName: string | null }[];
200	  /** true when this server already runs an older version of THIS Cyrus mod (an update, not a conflict) */
201	  update: boolean;
202	  notChecked: string[];
