208	export async function preinstallReport(a: {
209	  fs: ReadOnlyServerFs; base: string; records: HostRecord[]; mcVersion: string | null;
210	  candidate: { jarName: string; bytes: Buffer; pluginName: string | null; namespace: string; projectId: string };
211	  /** paths (relative to base) of this mod's previous files, from its delivery record (excluded: an update replaces them) */
212	  ownFiles?: string[];
213	}): Promise<PreinstallReport> {
214	  const inv = await scanServer(a.fs, { base: a.base });
215	  const own = new Set(a.ownFiles ?? []);
216	  const { mods, ctx } = inventoryEntries(inv, { exclude: (p) => own.has(p) });
217	  const cand = candidateJar(a.candidate.jarName, a.candidate.bytes, { id: `candidate:${a.candidate.jarName}`, cyrus: { namespace: a.candidate.namespace, projectId: a.candidate.projectId } });
218	  const rep = detectConflicts([cand, ...mods], { ...ctx, mcVersion: ctx.mcVersion ?? a.mcVersion ?? undefined });
219	  const mine = rep.findings.filter((f) => f.items.some((i) => i.mod === cand.id));
220	  const blocking: PreinstallFinding[] = mine.filter((f) => f.severity === "blocking").map((f) => ({ id: f.id, class: f.class, severity: "blocking" as const, message: f.message }));
221	  const warnings: PreinstallFinding[] = mine.filter((f) => f.severity !== "blocking").map((f) => ({ id: f.id, class: f.class, severity: "warning" as const, message: f.message })).slice(0, 50);
222	  const name = a.candidate.pluginName ? norm(a.candidate.pluginName) : null;
223	  const modsTab = a.records.filter((r) => r.via === "mods-tab" && r.status !== "REMOVED" && ((name && norm(r.name) === name) || (r.fileName && norm(r.fileName.replace(/\.jar$/i, "")) === norm(a.candidate.jarName.replace(/\.jar$/i, "")))));
224	  for (const r of modsTab) blocking.push({ id: `mods-tab:${norm(r.name)}`, class: "mods_tab_duplicate", severity: "blocking", message: `${r.name}${r.version ? ` ${r.version}` : ""} is installed from your Mods tab. Remove it there first, or the server would load two copies.` });
225	  const update = !!a.ownFiles?.length || a.records.some((r) => r.via === "cyrus" && !!name && norm(r.name) === name);
226	  return { ok: blocking.length === 0, blocking, warnings, modsTab: modsTab.map((r) => ({ name: r.name, version: r.version, fileName: r.fileName })), update, notChecked: rep.notChecked.slice(0, 30), plugins: inv.plugins.length };
227	}
