265	export async function loadServerContext(userId: string, serverId: string | null | undefined): Promise<ServerContext | null> {
266	  if (!serverId || !SERVER_PARAM_RE.test(serverId)) return null;
267	  const host = getHost();
268	  if (host.platform) {
269	    try {
270	      const api = host.platform.as(userId);
271	      const [s, inv] = await Promise.all([api.server(serverId), api.inventory(serverId)]);
272	      if (s.game !== "minecraft") return null;
273	      return { serverId, name: s.name, game: "minecraft", version: s.version, loader: s.loader, ramMB: s.ramMB, plugins: inv.records.filter((r) => r.status !== "REMOVED").map((r) => ({ name: r.name, version: r.version, via: r.via })) };
274	    } catch { return null; }
275	  }
276	  const row = (await host.servers.listForUser(userId)).find((s) => s.id === serverId);
277	  if (!row || host.servers.familyOf(row) !== "minecraft") return null;
278	  const plan = (row as { gamePlan?: { ramMB?: number | null } | null }).gamePlan;
279	  const records = (await host.records.allOnServer?.(serverId).catch(() => [])) ?? [];
280	  return {
281	    serverId, name: row.label || row.hostname, game: "minecraft", version: host.servers.pinnedVersion(row.gameConfig), loader: row.gameVariant, ramMB: plan?.ramMB ?? null,
282	    plugins: records.map((r) => ({ name: r.name, version: r.version, via: r.via })),
283	  };
284	}

