 65	  }
 66	  async mkdirp(p: string) {
 67	    await this.guard(() => this.api.mkdir(this.serverId, p, this.opts()));
 68	    this.known.set(p, "dir");
 69	  }
 70	  async rename(from: string, to: string) {
 71	    const ifMatch = await this.current(from), toIfMatch = await this.current(to);
 72	    await this.guard(() => this.api.rename(this.serverId, { from, to, ifMatch, toIfMatch }, this.opts()));
 73	    this.known.set(to, ifMatch); this.known.set(from, "absent");
 74	  }
 75	  async remove(p: string) {
 76	    const ifMatch = await this.current(p);
 77	    await this.guard(() => this.api.remove(this.serverId, { path: p, ifMatch }, this.opts()));
