 96	  const inv = await api.inventory(serverId, { opId: fs.opId });
 97	  const can = (s: PlatformScope) => scopes.includes(s);
 98	  const logText = async () => (can("logs.read.tail") ? (await api.logTail(serverId, o.logLines ?? 2000, { opId: fs.opId, rollback: fs.rollback })).lines.join("\n") : "");
