102	      if (!can("server.restart")) return { ok: false, error: "this connection does not allow restarts (server.restart): restart the server yourself to finish" };
103	      try { await api.restart(serverId, { opId: fs.opId, rollback: fs.rollback }); return { ok: true }; }
