107	      const log = parseBootLog(await logText().catch(() => ""));
108	      const live = await api.server(serverId, { live: true }).then((s) => s.live ?? null).catch(() => null);
109	      return {
110	        real: true, cameUp: log.cameUp, answered: !!live?.answered, pluginsEnabled: log.enabled, errorLines: log.errors, datapacksLoaded: live?.datapacksLoaded ?? [],
111	        evidence: [can("logs.read.tail") ? (log.cameUp ? "Done line found" : "no Done line") : "no log access (logs.read.tail)", live ? (live.answered ? "answers list" : "does not answer") : "no live probe"],
112	      };
113	    },
